def squash(s: str) -> str:
    if not s:
        return ""

    def esc(c: str) -> str:
        if c in '0123456789\\':
            return '\\' + c
        return c

    result = []
    i = 0
    n = len(s)

    while i < n:
        char = s[i]
        j = i
        while j < n and s[j] == char:
            j += 1
        run_length = j - i

        if run_length >= 3:
            result.append(str(run_length))
            result.append(esc(char))
        else:
            result.append(esc(char) * run_length)

        i = j

    return ''.join(result)
